import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";

import BookingList from "../components/BookingList";
import Navbar from "../components/Navbar";
import Sidebar from "../components/Sidebar";
import api from "../services/api";

const adminNavItems = [
  { key: "pending", label: "Pending", icon: "⌛" },
  { key: "schedule", label: "Schedule", icon: "▦" },
  { key: "history", label: "History", icon: "☷" }
];

const AdminDashboard = () => {
  const navigate = useNavigate();
  const [activeItem, setActiveItem] = useState("pending");
  const [pendingBookings, setPendingBookings] = useState([]);
  const [schedule, setSchedule] = useState([]);
  const [history, setHistory] = useState([]);
  const [message, setMessage] = useState("");

  const handleLogout = () => {
    localStorage.removeItem("token");
    navigate("/login");
  };

  const loadData = async () => {
    try {
      const [pendingResponse, scheduleResponse, historyResponse] = await Promise.all([
        api.get("/admin/bookings/pending"),
        api.get("/admin/schedule"),
        api.get("/admin/history")
      ]);

      setPendingBookings(pendingResponse.data);
      setSchedule(scheduleResponse.data);
      setHistory(historyResponse.data);
    } catch (error) {
      setMessage(error.response?.data?.detail || "Could not load dashboard data.");
    }
  };

  useEffect(() => {
    loadData();
  }, []);

  const handleApprove = async (bookingId) => {
    try {
      await api.post(`/admin/bookings/${bookingId}/approve`);
      setMessage("Booking approved.");
      await loadData();
    } catch (error) {
      setMessage(error.response?.data?.detail || "Approval failed.");
    }
  };

  const handleReject = async (bookingId) => {
    const reason = window.prompt("Enter rejection reason:");
    if (reason === null) {
      return;
    }

    try {
      await api.post(`/admin/bookings/${bookingId}/reject`, { reason });
      setMessage("Booking rejected.");
      await loadData();
    } catch (error) {
      setMessage(error.response?.data?.detail || "Rejection failed.");
    }
  };

  return (
    <div className="dashboard-shell">
      <Sidebar
        role="Admin"
        items={adminNavItems}
        activeItem={activeItem}
        onSelect={setActiveItem}
        onLogout={handleLogout}
      />

      <main className="dashboard-main">
        <Navbar
          title="Admin Control Panel"
          subtitle="Review pending requests, manage approvals, and monitor block schedules."
          userRole="Admin"
        />

        {message ? <div className="alert info">{message}</div> : null}

        <section className="summary-grid">
          <div className="metric-card">
            <p>Pending Requests</p>
            <h2>{pendingBookings.length}</h2>
          </div>
          <div className="metric-card">
            <p>Total Schedule Items</p>
            <h2>{schedule.length}</h2>
          </div>
          <div className="metric-card">
            <p>Processed History</p>
            <h2>{history.length}</h2>
          </div>
        </section>

        {activeItem === "pending" && (
          <BookingList
            title="Pending Bookings"
            description="Only bookings from your assigned block appear here."
            bookings={pendingBookings}
            onApprove={handleApprove}
            onReject={handleReject}
            showActions
            adminMode
          />
        )}

        {activeItem === "schedule" && (
          <BookingList
            title="Current Schedule"
            description="Full booking schedule for your block."
            bookings={schedule}
          />
        )}

        {activeItem === "history" && (
          <BookingList
            title="Booking History"
            description="Approved, rejected, and cancelled records for your block."
            bookings={history}
          />
        )}
      </main>
    </div>
  );
};

export default AdminDashboard;
